// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AppPolicyView) predicate.AppPolicyView {
	return predicate.AppPolicyView(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AppPolicyView) predicate.AppPolicyView {
	return predicate.AppPolicyView(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AppPolicyView) predicate.AppPolicyView {
	return predicate.AppPolicyView(sql.NotPredicates(p))
}
